function TrailPlayersDialog:Awake()
    local trailBattleMgr = TrailBattleMgr:GetInstance()
    ---@type TrailEnterDojo
    local trailEnterDojo = trailBattleMgr:GetEnterData()
    local noRanks = {}
    for i, v in pairs(trailEnterDojo.roomRank) do
        if checkInt(v.score) <= 0 then
            table.insert(noRanks, v)
        end
    end
    self.noRanks = noRanks
    self.GridView:InitGridView(#self.noRanks, Bind(self, self.OnGetGridItemByIndex))
end


---OnGetGridItemByIndex
