---@param gridView SuperScrollView.LoopGridView
---@param index number
---@param row number
---@param column number
function TrailPlayersDialog:OnGetGridItemByIndex(gridView, index, row, column)
    if index < 0 then
        return
    end
    local position = (index + 1)
    if position > #self.noRanks then
        return
    end
    local dojo = self.noRanks[position]
    local cell = gridView:NewListViewItem(PlayerCellItemNodePrefabName)
    local mBehaviour = GetLuaBehaviour(cell.gameObject, PlayerCellItemNodeLuaPath)
    if mBehaviour then
        if isNull(mBehaviour.Env) then
            mBehaviour:Init()
        end
        ---@type TrailPlayerItemCellNode
        local env = mBehaviour.Env
        env:FreshUI(dojo)
    end
    return cell
end

